-- Every seeded shop starts on the Growth plan so its products are live.
-- shop_is_live() gates public visibility on an active subscription, so
-- without this nothing would render.
insert into shop_subscriptions (shop_id, plan_id, status, current_period_end)
select s.id, p.id, 'active', now() + interval '1 year'
from shops s cross join plans p
where p.code = 'growth' and s.slug in ('bradlows', 'tubod')
  and not exists (select 1 from shop_subscriptions x where x.shop_id = s.id);

