   '/models/products/bradlows/sandton-sofa-3.glb', null, null, null),
  ('bradlows', 'sandton-sofa-2', 'Sandton 2-Seater Recliner Sofa', 'BRD-SAND-2S',
   '/models/products/bradlows/sandton-sofa-2.glb', null, null, null),
  ('bradlows', 'sandton-recliner', 'Sandton Recliner Armchair', 'BRD-SAND-1R',
   '/models/products/bradlows/sandton-recliner.glb', null, null, null),
  ('bradlows', 'oakwood-coffee-table', 'Oakwood Coffee Table', 'BRD-OAK-CT',
   '/models/products/bradlows/oakwood-coffee-table.glb', null, null, null),
  ('bradlows', 'woven-jute-rug', 'Woven Jute Rug 3.0 x 2.2m', 'BRD-JUTE-32',
   '/models/products/bradlows/woven-jute-rug.glb', null, null, null),
  ('tubod', 'pyc61001', 'PYC61001 Carrara Polished Porcelain 600x600', 'TUBOD-PYC61001',
