from products p join shops sh on sh.id = p.shop_id
join (values
  ('bradlows', 'sandton-sofa-3', 'living'),
  ('bradlows', 'sandton-sofa-3', 'dining'),
  ('bradlows', 'sandton-sofa-2', 'living'),
