-- Placement slots. Derived from the hand-authored layout: each existing
-- placement becomes a slot, so the current arrangement turns into
-- inventory that can be re-sold rather than being fixed forever.
insert into placement_slots (scene_id, room_id, code, label, category_code,
                             kind, room_type, x_mm, y_mm, z_mm, rotation_deg,
                             max_width_mm, max_depth_mm, is_premium)
select sc.id, r.id, v.code, v.label, v.cat, v.kind::product_kind,
       r.room_type, v.x, v.y, v.z, v.rot, v.maxw, v.maxd, v.premium
from scenes sc
cross join (values
  ('living', 'living-rug-1', 'Living rug position', 'rug', 'object',
   7800.0, 2300.0, 0, 0.0, 3450.0, 2530.0, false),
  ('living', 'living-sofa-2', 'Living sofa position', 'sofa', 'object',
   7900.0, 830.0, 0, 0.0, 2760.0, 1092.5, true),
  ('living', 'living-sofa-3', 'Living sofa position', 'sofa', 'object',
   6300.0, 2500.0, 0, -90.0, 2047.0, 1092.5, true),
  ('living', 'living-chair-4', 'Living chair position', 'chair', 'object',
   9400.0, 2500.0, 0, 90.0, 1334.0, 1690.5, false),
  ('living', 'living-table-5', 'Living table position', 'table', 'object',
   7700.0, 2350.0, 0, 0.0, 1380.0, 805.0, false)
) as v(room_code, code, label, cat, kind, x, y, z, rot, maxw, maxd, premium)
left join rooms r on r.scene_id = sc.id and r.code = v.room_code
where sc.slug = '3bed'
on conflict (scene_id, code) do update set label = excluded.label;

-- Live placements: fill each slot with the product it was authored with.
insert into placements (scene_id, slot_id, variant_id, shop_id, status, note)
select sc.id, sl.id, pv.id, p.shop_id, 'live', v.note
from scenes sc
join (values
  ('living-rug-1', 'bradlows', 'woven-jute-rug', 'Anchors the seating arrangement.'),
  ('living-sofa-2', 'bradlows', 'sandton-sofa-3', 'Backs onto the south wall, 125mm clear of it.'),
  ('living-sofa-3', 'bradlows', 'sandton-sofa-2', 'Faces east toward the recliner.'),
  ('living-chair-4', 'bradlows', 'sandton-recliner', 'Footrest extends west into the open floor.'),
  ('living-table-5', 'bradlows', 'oakwood-coffee-table', 'Off-centre west, clearing the recliner footrest by ~100mm.')
) as v(slot_code, shop, product, note) on true
join placement_slots sl on sl.scene_id = sc.id and sl.code = v.slot_code
join shops sh on sh.slug = v.shop
join products p on p.shop_id = sh.id and p.slug = v.product
join product_variants pv on pv.product_id = p.id and pv.is_default
where sc.slug = '3bed'
  and not exists (
    select 1 from placements x where x.slot_id = sl.id and x.status = 'live'
  );

-- Finish slots: which product dresses which room's floor. This is what
-- makes "who supplied this floor?" answerable for any surface.
insert into placement_slots (scene_id, room_id, code, label, category_code,
                             kind, room_type, material_name)
select sc.id, r.id, 'floor-' || r.code, r.name || ' floor', 'tile',
       'finish'::product_kind, r.room_type, v.material
from scenes sc
join (values
  ('master', 'tile_pyc61001'),
  ('wir', 'carpet'),
  ('bed3', 'tile_pyc61001'),
  ('bed2', 'tile_pyc61001'),
  ('living', 'tile_pyc61001'),
  ('dining', 'tile_pyc61001'),
  ('hall', 'tile_pyc61001')
) as v(room_code, material) on true
join rooms r on r.scene_id = sc.id and r.code = v.room_code
where sc.slug = '3bed'
on conflict (scene_id, code) do update set material_name = excluded.material_name;

-- Fill finish slots by matching the slot's material to the product
-- that supplies it. Unsold materials leave their slot empty.
insert into placements (scene_id, slot_id, variant_id, shop_id, status, note)
select sl.scene_id, sl.id, v.id, p.shop_id, 'live',
       'Floor finish supplied by ' || sh.name
from placement_slots sl
join scenes sc on sc.id = sl.scene_id
join product_variants v on v.material_name = sl.material_name
join products p on p.id = v.product_id
join shops sh on sh.id = p.shop_id
where sl.kind = 'finish'
  and sl.material_name is not null
  and p.status = 'published'
  and sc.slug = '3bed'
  and not exists (
    select 1 from placements x where x.slot_id = sl.id and x.status = 'live'
  );

commit;
